-- Parts catalogue and stock per branch at weighted average cost (D-06, T-74). Tables generated by
-- prisma migrate diff, then reviewed; checks and triggers are hand-written.

CREATE SCHEMA IF NOT EXISTS "inventory";

-- AlterEnum
ALTER TYPE "accounting"."JournalSource" ADD VALUE 'stock';

-- AlterTable
ALTER TABLE "accounting"."posting_settings" ADD COLUMN     "goods_received_account_id" UUID,
ADD COLUMN     "inventory_account_id" UUID,
ADD COLUMN     "stock_adjustment_account_id" UUID;

-- CreateTable
CREATE TABLE "inventory"."part" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "sku" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "name_ar" TEXT,
    "brand" TEXT,
    "unit" TEXT NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "part_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "inventory"."stock" (
    "company_id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "part_id" UUID NOT NULL,
    "on_hand" DECIMAL(14,3) NOT NULL DEFAULT 0,
    "value" DECIMAL(16,2) NOT NULL DEFAULT 0,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "stock_pkey" PRIMARY KEY ("branch_id","part_id")
);

-- CreateTable
CREATE TABLE "inventory"."stock_movement" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "branch_id" UUID NOT NULL,
    "part_id" UUID NOT NULL,
    "number" TEXT NOT NULL,
    "kind" TEXT NOT NULL,
    "quantity" DECIMAL(14,3) NOT NULL,
    "unit_cost" DECIMAL(14,4) NOT NULL,
    "value" DECIMAL(16,2) NOT NULL,
    "on_hand_after" DECIMAL(14,3) NOT NULL,
    "value_after" DECIMAL(16,2) NOT NULL,
    "reference" TEXT,
    "reason" TEXT,
    "idempotency_key" TEXT NOT NULL,
    "journal_id" UUID NOT NULL,
    "created_by" UUID NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "stock_movement_pkey" PRIMARY KEY ("id")
);

