CREATE UNIQUE INDEX "stock_movement_company_id_idempotency_key_key" ON "inventory"."stock_movement"("company_id", "idempotency_key");

-- AddForeignKey
ALTER TABLE "inventory"."stock" ADD CONSTRAINT "stock_company_id_part_id_fkey" FOREIGN KEY ("company_id", "part_id") REFERENCES "inventory"."part"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "inventory"."stock" ADD CONSTRAINT "stock_company_id_branch_id_fkey" FOREIGN KEY ("company_id", "branch_id") REFERENCES "org"."branch"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "inventory"."stock_movement" ADD CONSTRAINT "stock_movement_company_id_part_id_fkey" FOREIGN KEY ("company_id", "part_id") REFERENCES "inventory"."part"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "inventory"."stock_movement" ADD CONSTRAINT "stock_movement_company_id_branch_id_fkey" FOREIGN KEY ("company_id", "branch_id") REFERENCES "org"."branch"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written rules -------------------------------------------------------

ALTER TABLE inventory.part
  ADD CONSTRAINT part_sku_valid CHECK (sku ~ '^[A-Z0-9][A-Z0-9._/-]{0,39}$'),
  ADD CONSTRAINT part_unit_valid CHECK (unit IN ('each', 'litre', 'kg', 'metre', 'set'));

-- No negative stock, and no value without quantity (weighted average stays defined).
ALTER TABLE inventory.stock
  ADD CONSTRAINT stock_not_negative CHECK (on_hand >= 0 AND value >= 0),
  ADD CONSTRAINT stock_value_needs_quantity CHECK (on_hand > 0 OR value = 0);

ALTER TABLE inventory.stock_movement
  ADD CONSTRAINT stock_movement_kind_valid CHECK (kind IN ('receipt', 'adjustment_in', 'adjustment_out')),
  ADD CONSTRAINT stock_movement_positive CHECK (quantity > 0 AND unit_cost >= 0 AND value >= 0),
  ADD CONSTRAINT stock_movement_after CHECK (on_hand_after >= 0 AND value_after >= 0),
  ADD CONSTRAINT stock_movement_receipt_reference CHECK (kind <> 'receipt' OR reference IS NOT NULL),
  ADD CONSTRAINT stock_movement_adjustment_reason CHECK (kind = 'receipt' OR reason IS NOT NULL);

-- Movements are history; parts change only in name, brand and active flag (never SKU or unit).
CREATE TRIGGER stock_movement_immutable BEFORE UPDATE OR DELETE ON inventory.stock_movement
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();
CREATE OR REPLACE FUNCTION inventory.guard_part() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' OR NEW.sku <> OLD.sku OR NEW.unit <> OLD.unit OR NEW.company_id <> OLD.company_id THEN
    RAISE EXCEPTION 'part_identity_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER part_guard BEFORE UPDATE OR DELETE ON inventory.part
  FOR EACH ROW EXECUTE FUNCTION inventory.guard_part();

-- A stock balance only changes together with a movement that ends at the same figures.
CREATE OR REPLACE FUNCTION inventory.guard_stock() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'stock_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.on_hand <> 0 OR NEW.value <> 0 THEN
      RAISE EXCEPTION 'stock_starts_empty' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.on_hand, NEW.value) IS DISTINCT FROM (OLD.on_hand, OLD.value) AND NOT EXISTS (
       SELECT 1 FROM inventory.stock_movement m
        WHERE m.branch_id = NEW.branch_id AND m.part_id = NEW.part_id
          AND m.on_hand_after = NEW.on_hand AND m.value_after = NEW.value
          -- written by this same transaction
          AND m.xmin = (pg_current_xact_id()::text::bigint % 4294967296)::text::xid) THEN
    RAISE EXCEPTION 'stock_change_without_movement' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER stock_guard BEFORE INSERT OR UPDATE OR DELETE ON inventory.stock
  FOR EACH ROW EXECUTE FUNCTION inventory.guard_stock();

-- Permissions for company administrators.
UPDATE iam.role
   SET permissions = (
         SELECT array_agg(DISTINCT p ORDER BY p)
           FROM unnest(permissions || ARRAY['inventory.read', 'inventory.manage', 'inventory.adjust']) AS p),
       version = version + 1,
       updated_at = now()
 WHERE is_system AND code = 'company-admin';
